\end{align*}
satisfies $VI(K,\theta^*) = \epsilon$.
Moreover, we have that
\begin{align*}
D_1 = \frac{X(\theta^*)}{2\alpha}\leq \frac{E[\| \theta_1 - \theta^* \|^2]-E[\| \theta_{K+1} - \theta^* \|^2]}{2\alpha} \leq
\frac{E[\| \theta_1 - \theta^* \|^2]}{2\alpha} = C_1,
\end{align*} 
\begin{align*}
D_2 = \frac{c \sigma^2 \alpha}{2}
\leq 
\frac{\sigma^2 \alpha}{2} = C_2,
\end{align*}
and
\begin{align*}
(\epsilon - C_3) b - C_2
\leq \epsilon b - C_2
\leq 
\epsilon b - D_2.
\end{align*}
Accordingly, we have that 
