\end{align*}
Suppose that $VI(K,\theta^*) \leq \epsilon$.
Then, we have that
\begin{align*}
\frac{D_1}{K} + \frac{D_2}{b} \leq \epsilon,
\end{align*}
which implies that 
\begin{align*}
\overline{K}(b) := \frac{D_1 b}{\epsilon b - D_2} \leq K.
\end{align*}
Suppose that $VI(K,\theta^*) \geq \epsilon$.
Then, we have that
\begin{align*}
\frac{C_1}{K} + \frac{C_2}{b} + C_3 \geq \epsilon,
\end{align*}
which implies that 
\begin{align*}
\underline{K}(b) := \frac{C_1 b}{(\epsilon - C_3) b - C_2} \geq K.
\end{align*}
From \begin{align*}
D_1 = \frac{X(\theta^* )}{2\alpha}\leq\frac{E[\| \theta_1 - \theta^* \|^2]-E[\| \theta_{K+1} - \theta^* \|^2]}{2\alpha}
\leq\frac{E[\| \theta_1 - \theta^* \|^2]}{2\alpha} = C_1,
