\begin{align*}
D_2 = \frac{c \sigma^2 \alpha}{2}
\leq 
\frac{\sigma^2 \alpha}{2} = C_2,
\end{align*}
and
\begin{align*}
(\epsilon - C_3) b - C_2
\leq \epsilon b - C_2
\leq 
\epsilon b - D_2,
\end{align*}
we have that $\overline{K}(b) \leq \underline{K}(b)$.
Hence, $K$ with $VI(K,\theta^*) = \epsilon$ satisfies 
\begin{align*}
\overline{K}(b) \leq K \leq \underline{K}(b)
\end{align*}
and the SFO complexity $N = Kb$ satisfies  
