\frac{E[2\|\theta_1\|^2 + 2\gamma^2 \|E[\nabla f(\theta_1)]\|^2]}{2 \alpha} + \frac{\sigma^2 \alpha}{2b} + \frac{G^2 \alpha}{2},
\end{align*}
which implies that 
\begin{align*}
\frac{E[\nabla f(\theta_1)^\top \theta_1]}{\gamma} + \|E[\nabla f(\theta_1)]\|^2
\leq
\frac{E[\|\theta_1\|^2]}{\alpha \gamma}+ \frac{\gamma \|E[\nabla f(\theta_1)]\|^2}{\alpha}+ \frac{\sigma^2 \alpha}{2b \gamma} + \frac{G^2 \alpha}{2\gamma}.
